  vineShort: { holds: [[1.0, 1.25], [2.5, 2.875]], presses: [0.5], tol: 0.18, set: true, movers: [VINE(14, 2.9, 3.25, 2.875)], redBox: [[5, 5, 2.3]], redFloat: [[11, 13, 3.7, 4.7], [15, 15, 3.7, 4.7]], traps: [{ full: { presses: [0.5], holds: [[1.0, 1.25], [2.5, 3.5]] } }] },
