      if (m.x0 !== undefined) { m.x0 += X; m.x1 += X; }
      if (m.rail) { m.rail[0] += X; m.rail[2] += X; }
      if (m.orbit) m.orbit[0] += X;
      if (m.pivot) m.pivot[0] += X;
